<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Ubuntu Desktop</title>
<style>
*{box-sizing:border-box;margin:0;padding:0}
html,body{height:100%;overflow:hidden;font-family:Ubuntu, Cantarell, system-ui, sans-serif;background:#000}
#desktop{position:relative;width:100vw;height:100vh;background:linear-gradient(135deg,#2c001e,#5e2750 40%,#1a1a1a);overflow:hidden}
#wallpaper{position:absolute;inset:0}
#taskbar{position:absolute;left:0;right:0;bottom:0;height:56px;background:rgba(30,30,30,.85);backdrop-filter:blur(8px);display:flex;align-items:center;gap:8px;padding:0 12px;border-top:1px solid rgba(255,255,255,.08);z-index:1000}
#taskbar button{background:#3a3a3a;color:#eee;border:none;border-radius:8px;padding:8px 14px;cursor:pointer;font-weight:600}
#taskbar button:hover{background:#4a4a4a}
.window{position:absolute;min-width:360px;min-height:240px;width:640px;height:420px;background:#1e1e1e;color:#e6e6e6;border-radius:10px;box-shadow:0 20px 60px rgba(0,0,0,.6);border:1px solid #444;display:none;flex-direction:column;overflow:hidden}
.win-titlebar{height:36px;background:#2a2a2a;display:flex;align-items:center;justify-content:space-between;padding:0 10px;cursor:move;user-select:none}
.win-titlebar .title{font-weight:600;font-size:13px}
.win-close{background:transparent;border:none;color:#eee;font-size:18px;line-height:1;cursor:pointer;padding:0 6px;border-radius:4px}
.win-close:hover{background:#c01}
.win-body{flex:1;display:flex;flex-direction:column;overflow:hidden}
.files-toolbar{padding:8px;background:#252525;border-bottom:1px solid #333;display:flex;align-items:center;gap:10px}
#files-up{background:#3a3a3a;border:none;color:#eee;padding:4px 10px;border-radius:6px;cursor:pointer}
#files-up:hover{background:#4a4a4a}
#files-path{font-family:monospace;font-size:13px;color:#aee}
#files-list{flex:1;overflow:auto;padding:10px;display:grid;grid-template-columns:repeat(auto-fill,minmax(120px,1fr));gap:10px;background:#1e1e1e}
.fs-item{padding:10px;border-radius:8px;background:#2a2a2a;border:1px solid #333;display:flex;align-items:center;gap:8px;cursor:pointer}
.fs-item:hover{background:#333}
.fs-item.folder::before{content:"📁";font-size:18px}
.fs-item.file::before{content:"📄";font-size:18px}
.tabs-bar{display:flex;align-items:center;background:#252525;border-bottom:1px solid #333}
#tabs{display:flex;flex:1;overflow:auto}
.tab{padding:8px 12px;background:#2a2a2a;border-right:1px solid #333;white-space:nowrap;cursor:pointer;font-size:13px}
.tab.active{background:#1e1e1e;color:#fff;border-bottom:2px solid #7aa2f7}
.tab:hover{background:#333}
#new-tab{background:#3a3a3a;border:none;color:#eee;padding:6px 10px;border-radius:6px;margin:6px;cursor:pointer}
#new-tab:hover{background:#4a4a4a}
#editor{flex:1;width:100%;height:100%;background:#1e1e1e;color:#e6e6e6;border:none;outline:none;padding:12px;font-family:monospace;font-size:13px;resize:none}
</style>
</head>
<body>
<div id="desktop">
  <div id="wallpaper"></div>

  <div id="files-window" class="window" style="left:80px;top:80px">
    <div class="win-titlebar"><div class="title">Files</div><button class="win-close">×</button></div>
    <div class="win-body">
      <div class="files-toolbar">
        <button id="files-up">Up</button>
        <span id="files-path">/</span>
      </div>
      <div id="files-list"></div>
    </div>
  </div>

  <div id="notepad-window" class="window" style="left:200px;top:120px">
    <div class="win-titlebar"><div class="title">Notepad</div><button class="win-close">×</button></div>
    <div class="win-body">
      <div class="tabs-bar">
        <div id="tabs"></div>
        <button id="new-tab">+ New Tab</button>
      </div>
      <textarea id="editor" spellcheck="false"></textarea>
    </div>
  </div>

  <div id="taskbar">
    <button id="open-files">Files</button>
    <button id="open-notepad">Notepad</button>
  </div>
</div>

<script>
const desktop = document.getElementById('desktop');
let zIndexCounter = 10;

function showWindow(id){
  const w = document.getElementById(id);
  w.style.display = 'flex';
  w.style.zIndex = ++zIndexCounter;
}
document.getElementById('open-files').addEventListener('click',()=>showWindow('files-window'));
document.getElementById('open-notepad').addEventListener('click',()=>showWindow('notepad-window'));

document.querySelectorAll('.win-close').forEach(btn=>{
  btn.addEventListener('click',e=>{
    e.target.closest('.window').style.display='none';
  });
});

// draggable windows
document.querySelectorAll('.window').forEach(win=>{
  const title = win.querySelector('.win-titlebar');
  let dragging=false, ox=0, oy=0;
  title.addEventListener('mousedown',e=>{
    dragging=true; ox=e.clientX-win.offsetLeft; oy=e.clientY-win.offsetTop;
    win.style.zIndex=++zIndexCounter;
  });
  document.addEventListener('mousemove',e=>{
    if(!dragging) return;
    win.style.left=(e.clientX-ox)+'px';
    win.style.top=(e.clientY-oy)+'px';
  });
  document.addEventListener('mouseup',()=>dragging=false);
});

// Files app
const FS = {
  type:'dir',
  children:{
    bin:{type:'dir',children:{}},
    etc:{type:'dir',children:{}},
    home:{type:'dir',children:{
      user:{type:'dir',children:{
        Documents:{type:'dir',children:{
          'readme.txt':{type:'file'},
          'notes.md':{type:'file'}
        }},
        Downloads:{type:'dir',children:{
          'installer.deb':{type:'file'}
        }},
        Pictures:{type:'dir',children:{
          'photo1.jpg':{type:'file'}
        }},
        'todo.txt':{type:'file'}
      }}
    }},
    usr:{type:'dir',children:{}},
    var:{type:'dir',children:{}}
  }
};

let currentPath = '/';
const filesPathEl = document.getElementById('files-path');
const filesListEl = document.getElementById('files-list');
const filesUpBtn = document.getElementById('files-up');

function getNode(path){
  if(path==='/') return FS;
  const parts = path.split('/').filter(Boolean);
  let node = FS;
  for(const p of parts){
    if(!node.children || !node.children[p]) return null;
    node = node.children[p];
  }
  return node;
}

function renderFiles(){
  filesPathEl.textContent = currentPath;
  const node = getNode(currentPath);
  filesListEl.innerHTML='';
  if(!node || !node.children) return;
  Object.entries(node.children).forEach(([name,info])=>{
    const el = document.createElement('div');
    el.className = 'fs-item ' + (info.type==='dir'?'folder':'file');
    el.textContent = name;
    el.dataset.name = name;
    el.dataset.type = info.type;
    filesListEl.appendChild(el);
  });
}
filesUpBtn.addEventListener('click',()=>{
  if(currentPath==='/') return;
  const idx = currentPath.lastIndexOf('/');
  currentPath = currentPath.slice(0, idx) || '/';
  renderFiles();
});
filesListEl.addEventListener('dblclick',e=>{
  const item = e.target.closest('.fs-item');
  if(!item) return;
  if(item.dataset.type==='dir'){
    const name = item.dataset.name;
    currentPath = currentPath==='/' ? '/'+name : currentPath+'/'+name;
    renderFiles();
  }
});
renderFiles();

// Notepad app
const tabsContainer = document.getElementById('tabs');
const editor = document.getElementById('editor');
const newTabBtn = document.getElementById('new-tab');

let tabs = JSON.parse(localStorage.getItem('notepad-tabs')) || [];
if(tabs.length===0){
  tabs = [{id:Date.now().toString(), title:'Untitled', content:''}];
}
let activeTabId = tabs[0].id;

function saveTabs(){
  localStorage.setItem('notepad-tabs', JSON.stringify(tabs));
}
function renderTabs(){
  tabsContainer.innerHTML='';
  tabs.forEach(t=>{
    const el = document.createElement('div');
    el.className = 'tab' + (t.id===activeTabId?' active':'');
    el.textContent = t.title;
    el.dataset.id = t.id;
    el.addEventListener('click',()=>switchTab(t.id));
    tabsContainer.appendChild(el);
  });
}
function switchTab(id){
  activeTabId = id;
  const tab = tabs.find(t=>t.id===id);
  editor.value = tab ? tab.content : '';
  renderTabs();
}
editor.addEventListener('input',()=>{
  const tab = tabs.find(t=>t.id===activeTabId);
  if(tab){ tab.content = editor.value; saveTabs(); }
});
newTabBtn.addEventListener('click',()=>{
  const id = Date.now().toString();
  const newTab = {id, title:'Untitled', content:''};
  tabs.push(newTab);
  activeTabId = id;
  saveTabs();
  renderTabs();
  editor.value = '';
});
renderTabs();
switchTab(activeTabId);
</script>
</body>
</html>
